function text(selector,value,html=true){const el=$(selector);if(!el)return;if(Array.isArray(value)){[...el.children].forEach((child,i)=>{if(value[i]!==undefined)child.textContent=value[i]});return}if(el.matches('#project-form label')){if(el.firstChild?.nodeType===Node.TEXT_NODE)el.firstChild.textContent=value;return}html?el.innerHTML=value:el.textContent=value}
function translatePage(){const t=pageCopy[currentLanguage];document.documentElement.lang=currentLanguage==='zh'?'zh-Hans':'en';document.title=currentLanguage==='zh'?'Xi Mun — 数字营销与创意作品':'Xi Mun — Digital Marketing & Creative Work';$$(".desktop-nav a").forEach((el,i)=>el.textContent=t.nav[i]);$$(".mobile-nav a").forEach((el,i)=>el.textContent=t.nav[i]);text('.availability',t.availability);text('#edit-toggle',`${currentLanguage==='zh'?'编辑网站':'Edit this site'} <span>↗</span>`);text('.top-actions .button',t.cv);$('#resume-download').href=currentLanguage==='zh'?'assets/resumes/Ximun_Tang_Resume_ZH.pdf':'assets/resumes/Ximun_Tang_Resume_EN.pdf';text('#menu-toggle','☰',false);$('#menu-toggle').setAttribute('aria-label',t.mobileMenu);$('#language-toggle').textContent=currentLanguage==='en'?'中文':'English';text('.hero-copy .eyebrow',t.heroEyebrow);text('.hero-cta .button',t.explore);text('.hero-cta .quiet-link',t.aboutLink);text('.hero-foot span:first-child',t.location,false);text('#portrait-placeholder .portrait-hint',t.photoHint,false);text('#portrait-upload',t.photoButton);$('#portrait-image').alt=currentLanguage==='zh'?'Xi Mun 的个人照片':'Portrait of Xi Mun';const stamp=$$('.hero-stamp span');stamp.forEach((el,i)=>el.textContent=t.stamp[i]);text('.ticker-track span',t.ticker);text('#project-experience .section-heading .eyebrow',t.workEyebrow,false);text('#project-experience .section-heading h2',t.workTitle);text('#project-experience .section-aside',t.workAside);const filters=$$('.filter');filters.forEach((el,i)=>{el.innerHTML=t.filters[i]+(i===0?` <span id="all-count">${state.projects.length.toString().padStart(2,'0')}</span>`:'')});text('#add-project',t.addProject);text('.work-bottom>span',t.workBottom,false);text('.work-bottom>a',t.workLink);text('#about .about-left .eyebrow',t.aboutEyebrow,false);text('#about .about-left h2',t.aboutTitle);$$('.orbit-label').forEach((el,i)=>{el.textContent=t.orbit[i];el.setAttribute('aria-label',t.orbit[i])});text('.toolbox>span',t.toolbox,false);$$('.stat small').forEach((el,i)=>el.innerHTML=t.stats[i]);text('#experience .section-heading .eyebrow',t.experienceEyebrow,false);text('#experience .section-heading h2',t.experienceTitle);text('#experience .section-aside',t.experienceAside);renderExperience();renderSkills();renderLanguages();renderAchievements();text('.education-strip>.eyebrow',t.education,false);text('.education-strip div:nth-of-type(1) b',t.degree,false);text('.education-strip div:nth-of-type(2) b',t.exchange,false);text('#contact .eyebrow',t.contactEyebrow,false);text('#contact h2',t.contactTitle);text('#contact .contact-inner>p:not(.eyebrow)',t.contactCopy,false);text('footer>span',t.footer,false);text('footer>a:last-child',t.top,false);text('#project-form .eyebrow',t.dialogEyebrow,false);text('#project-form label:nth-of-type(1)',t.projectTitle,false);text('#project-form label:nth-of-type(2)',t.category,false);text('#project-form label:nth-of-type(3)',t.description,false);text('#project-form label:nth-of-type(4)',t.url,false);text('#project-form label:nth-of-type(5)',t.media,false);text('#project-form .button',t.save);text('#delete-project',t.delete,false);text('.dialog-close',t.cancel,false);const opts=$$('#project-form select option');opts.forEach((o,i)=>o.textContent=t.categories[i]);$$('.project-link').forEach(el=>el.firstChild.textContent=t.projectView);const empty=$('.project-empty');if(empty)empty.textContent=t.empty;}
function translateDataAttributes(){document.querySelectorAll('[data-en][data-zh]').forEach(el=>{el.innerHTML=el.dataset[currentLanguage]})}
function localizeExtras(){const zh=currentLanguage==='zh';translateDataAttributes();const form=$('#project-form');if(form){form.elements.title.placeholder=zh?'例如：一场有想法的品牌企划':'e.g. A campaign with a point of view';form.elements.description.placeholder=zh?'想法是什么？你做了什么？':'What was the idea? What did you do?';form.elements.url.placeholder='https://…'}$('.dialog-close').setAttribute('aria-label',pageCopy[currentLanguage].cancel);$('#language-toggle').setAttribute('aria-label',zh?'切换语言':'Switch language');$('#references').setAttribute('aria-label',zh?'工作推荐人':'Professional references');const meta=$('meta[name="description"]');meta.content=zh?'Xi Mun 的个人作品集：数字营销、内容创作与创意项目。':'The personal portfolio of Xi Mun — digital marketing, content and ideas in motion.'}function readState(){const published=window.XIMUN_PUBLISHED_DATA;if(published&&Array.isArray(published.projects)){state.projects=published.projects;state.texts=published.texts&&typeof published.texts==='object'?published.texts:{};state.textsZh=published.textsZh&&typeof published.textsZh==='object'?published.textsZh:{};state.publishedMedia=published.media&&typeof published.media==='object'?published.media:{}}try{const saved=JSON.parse(localStorage.getItem(storageKey)||'{}');if(Array.isArray(saved.projects))state.projects=saved.projects;if(saved.texts&&typeof saved.texts==='object')state.texts=saved.texts;if(saved.textsZh&&typeof saved.textsZh==='object')state.textsZh=saved.textsZh;if(state.textsZh[1]==='我是 Xi Mun，Taylor’s University 数字营销毕业生，擅长结合创意内容、受众洞察与执行力。')state.textsZh[1]='我是诗雯，泰莱大学市场营销专业毕业生。我喜欢用创意和别出心裁的想法，通过内容连接人与想法。'}catch(e){console.warn('Saved site data could not be read.',e)}state.projects=state.projects.map(p=>{const base=starterProjects.find(x=>x.id===p.id)||{};return {...p,photos:p.photos||base.photos||[]}});const groupSense=starterProjects.find(p=>p.id==='groupsense');if(groupSense&&!state.projects.some(p=>p.id==='groupsense')){const deltaIndex=state.projects.findIndex(p=>p.id==='delta-force');state.projects.splice(deltaIndex>=0?deltaIndex+1:0,0,{...groupSense});writeState()}}
function writeState(){try{localStorage.setItem(storageKey,JSON.stringify({projects:state.projects,texts:state.texts,textsZh:state.textsZh}))}catch(e){alert('Your browser storage is full. Export a backup and remove a large media file to continue.')}}
function openDb(){return new Promise((resolve,reject)=>{if(!('indexedDB'in window)){resolve(null);return}const req=indexedDB.open(mediaDb,1);req.onupgradeneeded=()=>req.result.createObjectStore('media');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
function getMedia(id){return new Promise(resolve=>{const fallback=()=>{const data=state.publishedMedia[id];resolve(data?dataToBlob(data):null)};if(!db){fallback();return}const req=db.transaction('media').objectStore('media').get(id);req.onsuccess=()=>req.result?resolve(req.result):fallback();req.onerror=fallback})}
function putMedia(id,file){return new Promise((resolve,reject)=>{if(!db){reject(new Error('Browser media storage is unavailable.'));return}const tx=db.transaction('media','readwrite');tx.objectStore('media').put(file,id);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error)})}
function removeMedia(id){return new Promise(resolve=>{if(!db){resolve();return}const tx=db.transaction('media','readwrite');tx.objectStore('media').delete(id);tx.oncomplete=()=>resolve();tx.onerror=()=>resolve()})}
async function mediaUrl(id){if(mediaUrls.has(id))return mediaUrls.get(id);const blob=await getMedia(id);if(!blob)return null;const url=URL.createObjectURL(blob);mediaUrls.set(id,url);return url}
function categoryName(c){return pageCopy[currentLanguage].categoryDisplay[c]||c}
const journeyTypeLabels={en:{origin:'HOMETOWN',chapter:'NEW CHAPTER',study:'EXCHANGE BASE',visited:'VISITED DESTINATION',return:'BACK TO MALAYSIA'},zh:{origin:'家乡',chapter:'新的篇章',study:'交换学习地',visited:'曾到访',return:'回到马来西亚'}};
function jtext(value){return value?.[currentLanguage]??value?.en??''}
function setJourneyPanel(kind,age,title,story){$('#journey-kind').textContent=kind;$('#journey-age').textContent=age;$('#journey-place').textContent=title;$('#journey-story-copy').textContent=story}
function setJourneyActiveChapter(id){journeyChapter=id;$$('.journey-chapter').forEach(button=>{const active=button.dataset.chapter===id;button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active))})}
function highlightJourneyMarker(id){journeyLocation=id;journeyMarkers.forEach((marker,key)=>{const el=marker.getElement?.();el?.classList.toggle('is-selected',key===id)});$$('.fallback-marker').forEach(marker=>marker.classList.toggle('is-selected',marker.dataset.location===id));$$('.destination-card').forEach(button=>button.classList.toggle('active',button.dataset.location===id))}
function focusJourneyLocation(id,zoom=5){const location=journeyData.locations.find(item=>item.id===id);if(!location)return;if(journeyMap)journeyMap.flyTo(location.coords,zoom,{duration:.8});else if(fallbackMapState)focusFallbackMap(location)}
function selectJourneyLocation(id,focus=true){const location=journeyData.locations.find(item=>item.id===id);if(!location)return;setJourneyActiveChapter(location.chapter);journeyPanelMode='location';highlightJourneyMarker(id);setJourneyPanel(journeyTypeLabels[currentLanguage][location.type],jtext(location.age),jtext(location.name),jtext(location.story));renderJourneyGallery(location);$('#journey-explorer').hidden=location.chapter!=='europe';if(location.chapter==='europe')renderJourneyDestinations();if(focus)focusJourneyLocation(id,location.chapter==='europe'?5:5.2)}
function setJourneyChapter(id,focusMap=true){const chapter=journeyData.chapters[id];if(!chapter)return;setJourneyActiveChapter(id);journeyPanelMode='chapter';highlightJourneyMarker(chapter.focus);setJourneyPanel(jtext(chapter.kind),jtext(chapter.age),jtext(chapter.title),jtext(chapter.story));renderJourneyGallery(journeyData.locations.find(x=>x.id===chapter.focus));$('#journey-explorer').hidden=id!=='europe';renderJourneyDestinations();if(!focusMap)return;if(id==='europe')focusFallbackEuropeOrMap();else focusJourneyLocation(chapter.focus,id==='return'?4.7:5.2)}

function renderJourneyDestinations(){const list=$('#journey-destinations');if(!list)return;list.replaceChildren();for(const location of journeyData.locations.filter(item=>item.chapter==='europe')){const button=document.createElement('button');button.type='button';button.className=`destination-card ${location.type}`;button.dataset.location=location.id;button.setAttribute('aria-pressed',String(location.id===journeyLocation));const dot=document.createElement('i');dot.className='destination-dot';const copy=document.createElement('span');copy.className='destination-copy';const name=document.createElement('b');name.textContent=jtext(location.name);const type=document.createElement('small');type.textContent=journeyTypeLabels[currentLanguage][location.type];copy.append(name,type);button.append(dot,copy);button.addEventListener('click',()=>selectJourneyLocation(location.id,true));list.append(button)}}
function setMapStatus(message,visible=true){const status=$('#journey-map-status');if(!status)return;status.textContent=message;status.hidden=!visible}
function journeyPopup(location){return `<div class="journey-popup"><b>${escapeHtml(jtext(location.name))}</b><small>${escapeHtml(journeyTypeLabels[currentLanguage][location.type])} · ${escapeHtml(jtext(location.age))}</small><p>${escapeHtml(jtext(location.story))}</p></div>`}
