function sanitizeMarkup(markup){const t=document.createElement('template');t.innerHTML=String(markup);const allowed=new Set(['BR','EM','STRONG','I','B']);const clean=node=>{for(const child of [...node.childNodes]){if(child.nodeType===Node.ELEMENT_NODE){clean(child);if(!allowed.has(child.tagName)){child.replaceWith(...child.childNodes)}else for(const attr of [...child.attributes])child.removeAttribute(attr.name)}else if(child.nodeType!==Node.TEXT_NODE)child.remove()}};clean(t.content);return t.innerHTML}
